class Solution {
    public int[] findOrder(int n, int[][] arr) {
       int[] indegree = new int[n];
       int[] ans = new int[n];
       for(int[] pair : arr){
            indegree[pair[0]]++;
       }
       LinkedList<Integer> stack = new LinkedList<>();
       for(int i=0; i<n; i++){
            if(indegree[i] == 0) stack.push(i);
       }
       int cnt=0;
       int idx=0;
       while(!stack.isEmpty()){
         int curr = stack.pop();
         cnt++;
         ans[idx++] = curr;
         for(int[] pair: arr){
            if(pair[1] == curr){
                indegree[pair[0]]--;
                if(indegree[pair[0]] == 0) stack.push(pair[0]);
            }
         }
       }
       return cnt == n ? ans : new int[]{};
    }
}


